function fixIcons(node, colorMap) {
  const out=[];
  function walk(n){
    if (n.type==='INSTANCE') {
      const mc = n.mainComponent;
      const nm = mc ? mc.name : '';
      if (nm.startsWith('Icon_')) {
        const col = n.getPluginData('tintColor') || colorMap.default;
        n.fills=[];
        const setDeep=(x)=>{ if ('fills' in x && x.fills && (x.type==='VECTOR'||x.type==='ELLIPSE'||x.type==='RECTANGLE'||x.type==='BOOLEAN_OPERATION'||x.type==='POLYGON')) { x.fills=[solid(col)]; } if ('children' in x) x.children.forEach(setDeep); };
        setDeep(n);
        out.push(nm);
      }
    }
    if ('children' in n) n.children.forEach(walk);
  }
  walk(node);
  return out;
}
