const mkCard=(parent,p,x,y,state)=>{
  const v=cardSet.children.find(c=>c.name==='State='+(state||'Default'));
  const i=v.createInstance(); parent.appendChild(i); i.name='ProductCard_'+p.name;
  const ph=i.findOne(n=>n.name==='Photo'); if(ph){ const c=P(p.photo); ph.fills=[{type:'IMAGE',imageHash:c.fills[0].imageHash,scaleMode:'FILL'}]; }
  const nm=i.findOne(n=>n.name==='Name'); if(nm) nm.characters=p.name;
  const ds=i.findOne(n=>n.name==='Desc'); if(ds) ds.characters=p.desc;
  const pr=i.findOne(n=>n.name==='Price'); if(pr) pr.characters=p.price;
  const ow=i.findOne(n=>n.name==='OldPriceWrap'); const ot=i.findOne(n=>n.name==='OldPrice');
  if(ow&&ot){ if(p.old){ ow.visible=true; ot.characters=p.old; ot.textAutoResize='WIDTH_AND_HEIGHT'; const w=Math.ceil(ot.width); ow.resize(w+2,26); const st=ow.findOne(n=>n.name==='Strike'); if(st) st.resize(w,1); } else ow.visible=false; }
  const bd=i.findOne(n=>n.name==='Badge');
  if(bd){ if(p.badge){ bd.visible=true; bd.swapComponent(badgeSet.children.find(c=>c.name==='Type='+(p.badge==='New'?'New':'Sale'))); const bt=bd.findOne(n=>n.type==='TEXT'); if(bt) bt.characters=p.badge; } else bd.visible=false; }
  i.x=x;i.y=y; return i;
};

