const page=figma.root.children.find(p=>p.id==='15:2');
await figma.setCurrentPageAsync(page);
const keepIds=['24:29','27:300','29:421','30:574','30:647','33:665','33:766','34:808','34:916'];
const keep=new Set(keepIds);
const dupes=page.children.filter(c=>c.type==='FRAME'&&c.width===1440&&!keep.has(c.id));
const removed=dupes.map(c=>c.name+' '+c.id);
dupes.forEach(c=>c.remove());
// dedupe overlapping hotspots on kept screens: same parent, same name, same x/y
let pruned=0;
page.children.filter(c=>c.type==='FRAME'&&keep.has(c.id)).forEach(f=>{
  const seen=new Set();
  f.children.filter(c=>c.name.startsWith('Hotspot_')).forEach(h=>{
    const key=h.name+'|'+Math.round(h.x)+'|'+Math.round(h.y);
    if(seen.has(key)){ h.remove(); pruned++; } else seen.add(key);
  });
});
const frames=page.children.filter(c=>c.type==='FRAME');
const screens=frames.filter(f=>f.width===1440);
const ids=new Set(screens.map(f=>f.id));
let links=0, broken=0;
page.findAll(n=>n.reactions&&n.reactions.length).forEach(n=>n.reactions.forEach(r=>r.actions.forEach(a=>{ if(a.destinationId){ if(ids.has(a.destinationId)) links++; else broken++; } })));
return {removed, pruned, screens:screens.map(f=>({name:f.name,id:f.id,h:Math.round(f.height),links:f.findAll(n=>n.reactions&&n.reactions.length).length})), links, broken, libraryPresent: frames.some(f=>f.name==='Furniro · Component Library')};

